  (intern.nokkel_id('hendelse', '2025-09-30|rollebytte|tromso-kommune-administrasjonen|Stig Tore Johnsen fratrer som kommunedirektør'), '2025-09-30|rollebytte|tromso-kommune-administrasjonen|Stig Tore Johnsen fratrer som kommunedirektør', '2025-09-30', 'dag', 'rollebytte', 'Stig Tore Johnsen fratrer som kommunedirektør', 'Mari Enoksen Hult ble fungerende eller konstituert kommunedirektør, før Ellen Beate Lundberg tok over. Datoen for overgangen til Lundberg er ikke oppgitt.', intern.nokkel_id('organisasjon', 'tromso-kommune-administrasjonen'), null, array[intern.nokkel_id('person', 'stig-tore-johnsen'), intern.nokkel_id('person', 'mari-enoksen-hult'), intern.nokkel_id('person', 'ellen-beate-lundberg')]::uuid[], intern.nokkel_id('kilde', 'tromso-kommune-no'), 'oppgitt', '2025-09-30', null, null),
  (intern.nokkel_id('hendelse', '2025|valg|stortinget-troms-valgkrets|Stortingsvalget 2025'), '2025|valg|stortinget-troms-valgkrets|Stortingsvalget 2025', '2025', 'aar', 'valg', 'Stortingsvalget 2025', 'Representantene fra Troms valgkrets sitter i perioden 2025–2029.', intern.nokkel_id('organisasjon', 'stortinget-troms-valgkrets'), null, '{}'::uuid[], intern.nokkel_id('kilde', 'data-stortinget-no'), 'oppgitt', '2025', null, null),
  (intern.nokkel_id('hendelse', '2026-05-04|utbytte|troms-kraft|Troms Kraft-styret foreslår 175 mill. kr i utbytte'), '2026-05-04|utbytte|troms-kraft|Troms Kraft-styret foreslår 175 mill. kr i utbytte', '2026-05-04', 'dag', 'utbytte', 'Troms Kraft-styret foreslår 175 mill. kr i utbytte', '105 mill. kr går til Troms Holding og 70 mill. kr til Tromsø kommune.', intern.nokkel_id('organisasjon', 'troms-kraft'), null, '{}'::uuid[], intern.nokkel_id('kilde', 'nrk'), 'oppgitt', '2026-05-04', 'Datoen er datoen for NRK-saken. Når styret fremmet forslaget, er ikke oppgitt.', null),
  (intern.nokkel_id('hendelse', '2026-06-24|regnskap|tromso-kommunestyre|Kommunestyret godkjenner regnskapet for 2025'), '2026-06-24|regnskap|tromso-kommunestyre|Kommunestyret godkjenner regnskapet for 2025', '2026-06-24', 'dag', 'regnskap', 'Kommunestyret godkjenner regnskapet for 2025', 'Ifølge NRK brukte kommunen 66 millioner kroner for mye i 2025.', intern.nokkel_id('organisasjon', 'tromso-kommunestyre'), null, '{}'::uuid[], intern.nokkel_id('kilde', 'nrk'), 'oppgitt', '2026-06-24', null, null),
  (intern.nokkel_id('hendelse', '2026-09-23|vedtak|vefsn-kommune-administrasjonen|Vefsn kommunestyre ansatte Asbjørn Engum som kommunedirektør'), '2026-09-23|vedtak|vefsn-kommune-administrasjonen|Vefsn kommunestyre ansatte Asbjørn Engum som kommunedirektør', '2026-09-23', 'dag', 'vedtak', 'Vefsn kommunestyre ansatte Asbjørn Engum som kommunedirektør', 'Kommunestyret vedtok enstemmig arbeidsutvalgets anbefaling. Engum er kommunedirektør i Hattfjelldal. Startdato var ikke avklart.', intern.nokkel_id('organisasjon', 'vefsn-kommune-administrasjonen'), null, array[intern.nokkel_id('person', 'asbjorn-engum')]::uuid[], intern.nokkel_id('kilde', 'vefsn-kommune-no'), 'oppgitt', '2026-09-25', 'Hentet fra vefsn.kommune.no/nyhetsarkiv/nyheter-forside/2026-09-23-asbjorn-60-blir-ny-kommunedirektor 2026-09-25.', null),
  (intern.nokkel_id('hendelse', '2026-11-20|planlagt|finnmarkskommisjonen|Frist for å melde inn rettigheter i felt 8 Kautokeino'), '2026-11-20|planlagt|finnmarkskommisjonen|Frist for å melde inn rettigheter i felt 8 Kautokeino', '2026-11-20', 'dag', 'planlagt', 'Frist for å melde inn rettigheter i felt 8 Kautokeino', 'Finnmarkskommisjonen kartlegger grunnen i Kautokeino kommune som FeFo overtok i 2006.', intern.nokkel_id('organisasjon', 'finnmarkskommisjonen'), null, '{}'::uuid[], intern.nokkel_id('kilde', 'domstol-no-finnmarkskommisjonen'), 'oppgitt', '2026-09-25', 'Hentet fra domstol.no 25.09.2026.', null),
  (intern.nokkel_id('hendelse', '2027-01|planlagt|troms-fylkesting|Perioden som fungerende fylkesordfører ventes å ende'), '2027-01|planlagt|troms-fylkesting|Perioden som fungerende fylkesordfører ventes å ende', '2027-01', 'maaned', 'planlagt', 'Perioden som fungerende fylkesordfører ventes å ende', 'Benjamin Nordberg Furuly er fungerende fylkesordfører fram til midten av januar 2027.', intern.nokkel_id('organisasjon', 'troms-fylkesting'), null, array[intern.nokkel_id('person', 'benjamin-nordberg-furuly')]::uuid[], intern.nokkel_id('kilde', 'tromsfylke-no'), 'oppgitt', '2026-09', null, null),
  (intern.nokkel_id('hendelse', '2027|planlagt|tromso-kommunestyre|Kommunestyrevalget 2027'), '2027|planlagt|tromso-kommunestyre|Kommunestyrevalget 2027', '2027', 'aar', 'planlagt', 'Kommunestyrevalget 2027', null, intern.nokkel_id('organisasjon', 'tromso-kommunestyre'), null, '{}'::uuid[], intern.nokkel_id('kilde', 'researchgrunnlag'), 'maa_verifiseres', '2026-09', 'Grunnlaget oppgir ikke kilde for dette.', null),
  (intern.nokkel_id('hendelse', '2027|strukturdebatt|tromso-kommune|Byrådsmodell etter valget 2027 er foreslått'), '2027|strukturdebatt|tromso-kommune|Byrådsmodell etter valget 2027 er foreslått', '2027', 'aar', 'strukturdebatt', 'Byrådsmodell etter valget 2027 er foreslått', 'Nordlys (redaksjonelt) og FrP har tatt til orde for å gjeninnføre byråd etter valget 2027. Sp og Rødt er skeptiske. Ingen vedtak er fattet.', intern.nokkel_id('organisasjon', 'tromso-kommune'), null, '{}'::uuid[], intern.nokkel_id('kilde', 'nrk'), 'oppgitt', '2026-09', 'NRK er kilde for at byrådsmodellen diskuteres på nytt etter underskuddet. Grunnlaget oppgir ikke kilde for partienes standpunkter.', null)
