-- Hull
on conflict (key) do update set
  org_id = excluded.org_id,
  hva = excluded.hva,
  hvorfor = excluded.hvorfor,
  personer = excluded.personer;

-- Regionen
on conflict (key) do update set
  navn = excluded.navn,
  sammenstilt = excluded.sammenstilt,
  merknad = excluded.merknad;

-- Regionregisteret: fjern det som ikke står i registeret
delete from region_kommune where slug not in ('bodo', 'narvik', 'bindal', 'somna', 'bronnoy', 'vega', 'vevelstad', 'heroy', 'alstahaug', 'leirfjord', 'vefsn', 'grane', 'hattfjelldal', 'donna', 'nesna', 'hemnes', 'rana', 'luroy', 'traena', 'rodoy', 'meloy', 'gildeskal', 'beiarn', 'saltdal', 'fauske', 'sorfold', 'steigen', 'lodingen', 'evenes', 'rost', 'vaeroy', 'flakstad', 'vestvagoy', 'vagan', 'hadsel', 'bo', 'oksnes', 'sortland', 'andoy', 'moskenes', 'hamaroy', 'tromso', 'harstad', 'kvaefjord', 'tjeldsund', 'ibestad', 'gratangen', 'lavangen', 'bardu', 'salangen', 'malselv', 'sorreisa', 'dyroy', 'senja', 'balsfjord', 'karlsoy', 'lyngen', 'storfjord', 'kafjord', 'skjervoy', 'nordreisa', 'kvaenangen', 'alta', 'hammerfest', 'sor-varanger', 'vadso', 'karasjok', 'kautokeino', 'loppa', 'hasvik', 'masoy', 'nordkapp', 'porsanger', 'lebesby', 'gamvik', 'tana', 'berlevag', 'batsfjord', 'vardo', 'nesseby');
